edits.replacement:
#root #title #slotpanel button, #root #title #pnamein{ min-height:var(--btn-h-xs); border-radius:var(--rad) !important; font:600 var(--fs-label)/1 var(--f-cond) !important; }
/* v28.xx (cw-uishared-title2), the critic scored the title 2 of 5 ("template page, cards read as buttons, five amber things, rows off the grid,
   no pad focus"). Cards are flat columns under a 1px rule, not boxes; one amber per zone; every mode row 48px on the 8px grid; a focus cue. */
#root #title .tcard{ background:transparent; border:0; border-top:1px solid var(--ui-line-hi); border-radius:0; box-shadow:none; padding:var(--sp-2) var(--sp-1) 0 0; }
#root #title .tstep{ color:var(--acc); }
#root #title .titlecol > div[style*="grid"]{ margin-top:var(--sp-3) !important; gap:var(--sp-4) !important; }
#root #title .kbrow, #root #title .padrow{ margin-top:var(--sp-3) !important; }
#root #title .kbrow b{ font-size:var(--fs-fine) !important; }
#root #title #modemenu button.moderow:focus-visible{ outline:none; background:var(--ui-raised); border-color:var(--acc); box-shadow:inset 3px 0 0 var(--acc); }
#root #title #slotpanel #pnamesave, #root #title #slotpanel #newgame{ background:transparent; border:1px solid var(--ui-line-hi) !important; color:var(--tx-1) !important; }
#root #title #slotpanel #pnamein{ text-transform:none; }
</style>

check:
{v:'VER',what:'the title is calmer on the shared look: the three step cards are flat columns (no box), every mode row is 48px or more on the 8px grid, the step numbers carry the one accent, the save buttons are not accent text (critic 2 of 5)',
 run:function(){
   var t=document.querySelector('#title .tcard'), s=document.querySelector('#title .tstep'), r, i, ids=['modecoop','modearcade','modearcade1','modecoopsrv','modepvp','modepvpsrv'], h, cs;
   if(!t||!s) return 'no step card';
   cs=getComputedStyle(t);
   if(cs.borderLeftWidth!=='0px'||cs.borderRightWidth!=='0px'||cs.borderBottomWidth!=='0px') return 'the step card still has a box border';
   if(cs.borderTopLeftRadius!=='0px') return 'the step card still has rounded corners';
   for(i=0;i<ids.length;i++){ r=document.getElementById(ids[i]); if(!r) return 'no row '+ids[i]; h=parseFloat(getComputedStyle(r).minHeight); if(h<48||h%8) return ids[i]+' row is '+h+'px min height, not 48 on the 8px grid'; }
   if(getComputedStyle(s).color===getComputedStyle(t.querySelector('.tbody')).color) return 'the step number does not carry the accent';
   if(getComputedStyle(document.getElementById('newgame')).color===getComputedStyle(document.getElementById('titlestart')).backgroundColor) return 'the create save button is still accent text';
   return null;
 }},
